<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {ArrowUpRight,ArrowRight,Leaf,HeartHandshake,ShieldCheck,Search,SlidersHorizontal,Sprout,PackageCheck,MapPin} from 'lucide-vue-next'
import BatchCard from '../components/BatchCard.vue'
import {api,type Batch} from '../api'
const items=ref<Batch[]>([]),loading=ref(true),error=ref(''),category=ref(''),search=ref('')
const impact=ref({completed_batches:0,completed_weight_kg:0,completed_claims:0})
const filtered=computed(()=>items.value.filter(b=>(!category.value||b.category===category.value)&&`${b.title} ${b.area} ${b.donor_name}`.toLowerCase().includes(search.value.toLowerCase())))
const categories=[['','全部余量'],['bakery','烘焙食品'],['produce','新鲜果蔬'],['packaged','包装食品'],['prepared','即食餐食']]
async function load(){loading.value=true;error.value='';try{const [b,i]=await Promise.all([api<{items:Batch[]}>('/batches?limit=100'),api<typeof impact.value>('/impact')]);items.value=b.items;impact.value=i}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
onMounted(load)
</script>
